@startuml
layout portrait
interface Playable {
  + duration(): int
  + play(queue)
}
class Song {
  - title
  - seconds
  + duration(): int
  + play(queue)
}
class Playlist {
  - name
  + add(item: Playable)
  + duration(): int
  + play(queue)
}
Song ..|> Playable
Playlist ..|> Playable
Playlist o--> "*" Playable : items
@enduml

